"use strict";
const fs = require("fs");
const assert = require("assert");
const line = fs.readFileSync("screen.txt", "utf8").trim();
const p = /^(0\.\d{3}),(0\.\d{3})$/.exec(line);
assert.ok(p, "screen.txt must be X,Y fractions with three decimals, got: " + line);
assert.ok(Math.abs(+p[1] - 0.25) < 0.01 && Math.abs(+p[2] - 0.75) < 0.01, "pointer must have reached (0.25, 0.75), got " + line);
console.log("ok: pointer " + line);

